<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
import CouponManager from './CouponManager.vue'
const $q=useQuasar(), rows=ref([]), search=ref(''), loading=ref(false), dialog=ref(false), couponAffiliate=ref(null)
const blank=()=>({_id:'',name:'',email:'',phone:'',active:true,instagram:'',tiktok:'',youtube:''}), form=reactive(blank())
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}})
const columns=[{name:'name',label:'Afiliado',field:'name',align:'left'},{name:'email',label:'E-mail',field:'email',align:'left'},{name:'active',label:'Acesso',field:r=>r.active?'Ativo · MFA obrigatório':'Suspenso',align:'left'},{name:'actions',label:'',align:'right'}]
const required=v=>Boolean(String(v||'').trim())||'Informe este campo.'
function open(row){Object.assign(form,blank(),row||{});dialog.value=true}
function error(e){$q.notify({type:'negative',message:e.response?.data?.message||'Não foi possível concluir a operação.'})}
async function load(){loading.value=true;try{rows.value=(await api.get('/admin/affiliates',{...headers(),params:{q:search.value}})).data.data||[]}catch(e){error(e)}finally{loading.value=false}}
async function save(){loading.value=true;try{const body={name:form.name,email:form.email,phone:form.phone,active:form.active,instagram:form.instagram,tiktok:form.tiktok,youtube:form.youtube};if(form._id||form.id)await api.put('/admin/affiliates/'+(form._id||form.id),body,headers());else await api.post('/admin/affiliates',body,headers());dialog.value=false;await load();$q.notify({type:'positive',message:'Afiliado salvo. Acesso somente com código por e-mail.'})}catch(e){error(e)}finally{loading.value=false}}
function remove(row){$q.dialog({title:'Suspender afiliado',message:'Suspender '+row.name+' e seus cupons? Vendas e comissões anteriores serão preservadas.',cancel:true,persistent:true}).onOk(async()=>{try{await api.delete('/admin/affiliates/'+row._id,headers());await load()}catch(e){error(e)}})}
async function copy(){try{await navigator.clipboard.writeText(window.location.origin+'/affiliate/login');$q.notify({type:'positive',message:'Link de acesso copiado.'})}catch{$q.notify({type:'info',message:window.location.origin+'/affiliate/login'})}}
onMounted(load)
</script>
<template><section class="partners"><header><div><small>PROGRAMA DE AFILIADOS</small><h2>Parceiros do kit</h2><p>AitoNotify + WhatsApp BotBuilder · acesso por e-mail, sem senha.</p></div><div class="row q-gutter-sm"><q-btn outline no-caps icon="mdi-link" label="Link de acesso" @click="copy"/><q-btn unelevated no-caps color="teal-8" icon="mdi-plus" label="Novo afiliado" @click="open()"/></div></header><q-input v-model="search" outlined dense clearable label="Buscar por nome ou e-mail" debounce="350" @update:model-value="load"/><q-table flat bordered wrap-cells row-key="_id" :rows="rows" :columns="columns" :loading="loading" no-data-label="Nenhum afiliado cadastrado"><template #body-cell-actions="p"><q-td :props="p"><q-btn flat round dense color="teal-8" icon="mdi-ticket-percent-outline" aria-label="Configurar cupons" @click="couponAffiliate=p.row"><q-tooltip>Cupons, descontos e comissão</q-tooltip></q-btn><q-btn flat round dense icon="mdi-pencil-outline" aria-label="Editar afiliado" @click="open(p.row)"/><q-btn flat round dense color="negative" icon="mdi-account-cancel-outline" aria-label="Suspender afiliado" @click="remove(p.row)"/></q-td></template></q-table><q-dialog v-model="dialog" persistent><q-card class="partner-dialog"><q-card-section class="row justify-between items-center"><strong>{{form._id?'Editar afiliado':'Cadastrar afiliado'}}</strong><q-btn flat round dense icon="mdi-close" v-close-popup/></q-card-section><q-form @submit.prevent="save"><q-card-section class="q-gutter-md"><q-banner rounded class="bg-teal-1 text-teal-10">O afiliado recebe um código no e-mail sempre que solicita acesso. Não há senha para esse perfil.</q-banner><q-input v-model.trim="form.name" outlined label="Nome" :rules="[required]"/><q-input v-model.trim="form.email" outlined type="email" label="E-mail de acesso e multifator" :rules="[required]"/><q-input v-model.trim="form.phone" outlined label="Telefone (opcional)"/><q-input v-model.trim="form.instagram" outlined label="Instagram (opcional)"/><q-toggle v-model="form.active" label="Acesso ativo" color="teal-8"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" v-close-popup/><q-btn unelevated color="teal-8" no-caps type="submit" label="Salvar afiliado" :loading="loading"/></q-card-actions></q-form></q-card></q-dialog><q-dialog :model-value="Boolean(couponAffiliate)" @update:model-value="v=>{if(!v)couponAffiliate=null}"><q-card class="partner-coupons"><q-card-section class="row justify-between items-center"><strong>{{couponAffiliate?.name}}</strong><q-btn flat round dense icon="mdi-close" @click="couponAffiliate=null"/></q-card-section><q-card-section><CouponManager v-if="couponAffiliate" :affiliate-id="couponAffiliate._id"/></q-card-section></q-card></q-dialog></section></template>
<style scoped>.partners{display:grid;gap:22px;color:#244c3a}.partners>header{display:flex;align-items:center;justify-content:space-between;gap:18px}.partners small{color:#26846a;font-size:10px;letter-spacing:.13em;font-weight:800}.partners h2{font-size:27px;font-weight:750;line-height:1.3;margin:8px 0}.partners p{color:#668677;font-size:13px}.partners :deep(.q-table__container){background:#fff;color:#2e5842;border-color:#cde4d6;border-radius:15px}.partner-dialog{width:min(560px,94vw);border-radius:20px;background:#f5fcf8;color:#234d38}.partner-coupons{width:min(1100px,96vw);max-width:96vw;background:#f5fcf8;border-radius:20px;color:#234d38}@media(max-width:700px){.partners>header{align-items:start;flex-direction:column}}</style>
